import numpy as np
X=np.load('X.npy'); y=np.load('y.npy'); Xs=np.load('Xs.npy')
tx=[tobytes(x) for x in np.ascontiguousarray(X).reshape(len(X),-1)]
# build dict
d={}
for i,t in enumerate(tx): d.setdefault(t,[]).append(i)
cnt=0; lab=[]; nomatch=0
for j,x in enumerate(Xs.reshape(len(Xs),-1)):
    t=x.tobytes()
    if t in d:
        cnt+=1
        lab.append(y[d[t][0]])
    else:
        nomatch+=1
print('test images found in train:',cnt,'not found:',nomatch)
print('derived test label counts', np.bincount(lab))
""}

